const std = @import("std");

const Allocator = std.mem.Allocator;
const ArrayListUnmanaged = std.ArrayListUnmanaged;
const StringHashMap = std.StringHashMap;
const Sha256 = std.crypto.hash.sha2.Sha256;

const StoredChar = struct {
    bytes: [4]u8,
    len: u8,
    pos: usize,
    timestamp_ms: i128,
    hash: [32]u8,
    surprise_score: f32,
};

const Message = struct {
    role: []const u8,
    content: []const u8,
};

const ChatResponse = struct {
    choices: []const struct {
        message: struct {
            content: ?[]const u8 = null,
        },
    },
};

const ConversationHistory = struct {
    allocator: Allocator,
    filename: []const u8,
    chars: ArrayListUnmanaged(StoredChar),
    seen: StringHashMap(void),
    session_id: [16]u8,

    pub fn init(allocator: Allocator, filename: []const u8) !ConversationHistory {
        var self = ConversationHistory{
            .allocator = allocator,
            .filename = try allocator.dupe(u8, filename),
            .chars = .empty,
            .seen = StringHashMap(void).init(allocator),
            .session_id = undefined,
        };
        errdefer self.cleanup();
        std.crypto.random.bytes(&self.session_id);
        try self.loadFromFile();
        return self;
    }

    pub fn deinit(self: *ConversationHistory) void {
        self.saveToFile() catch {};
        self.cleanup();
    }

    fn cleanup(self: *ConversationHistory) void {
        self.freeSeenKeys();
        self.seen.deinit();
        self.chars.deinit(self.allocator);
        self.allocator.free(self.filename);
    }

    fn freeSeenKeys(self: *ConversationHistory) void {
        var it = self.seen.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
    }

    fn loadFromFile(self: *ConversationHistory) !void {
        const file = std.fs.cwd().openFile(self.filename, .{}) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        defer file.close();

        const stat = try file.stat();
        if (stat.size == 0) return;

        const max_size = std.math.cast(usize, stat.size) orelse return error.FileTooBig;
        const data = try file.readToEndAlloc(self.allocator, max_size);
        defer self.allocator.free(data);

        var lines = std.mem.splitScalar(u8, data, '\n');
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            var parts = std.mem.splitScalar(u8, line, '\t');
            const pos_str = parts.next() orelse continue;
            const ts_str = parts.next() orelse continue;
            const surprise_str = parts.next() orelse continue;
            const hash_hex = parts.next() orelse continue;
            const char_hex = parts.next() orelse continue;

            var hash: [32]u8 = undefined;
            if (hash_hex.len != 64) continue;
            _ = std.fmt.hexToBytes(&hash, hash_hex) catch continue;

            if (char_hex.len == 0 or char_hex.len > 8 or char_hex.len % 2 != 0) continue;
            var char_bytes: [4]u8 = [_]u8{0} ** 4;
            const decoded = std.fmt.hexToBytes(&char_bytes, char_hex) catch continue;
            if (decoded.len == 0 or decoded.len > 4) continue;
            _ = std.unicode.Utf8View.init(decoded) catch continue;

            const parsed_pos = std.fmt.parseInt(usize, pos_str, 10) catch continue;
            const parsed_timestamp = std.fmt.parseInt(i128, ts_str, 10) catch continue;
            const parsed_surprise = std.fmt.parseFloat(f32, surprise_str) catch continue;

            var canonical_hash_hex_buf: [64]u8 = undefined;
            const canonical_hash_hex = std.fmt.bufPrint(&canonical_hash_hex_buf, "{}", .{std.fmt.fmtSliceHexLower(&hash)}) catch unreachable;
            if (self.seen.contains(canonical_hash_hex)) continue;

            const stored = StoredChar{
                .bytes = char_bytes,
                .len = @intCast(decoded.len),
                .pos = parsed_pos,
                .timestamp_ms = parsed_timestamp,
                .hash = hash,
                .surprise_score = parsed_surprise,
            };

            const owned_key = try self.allocator.dupe(u8, canonical_hash_hex);
            errdefer self.allocator.free(owned_key);
            try self.chars.append(self.allocator, stored);
            try self.seen.put(owned_key, {});
        }
    }

    fn saveToFile(self: *ConversationHistory) !void {
        const file = try std.fs.cwd().createFile(self.filename, .{ .truncate = true });
        defer file.close();

        var bw = std.io.bufferedWriter(file.writer());
        const writer = bw.writer();

        for (self.chars.items) |item| {
            const char_len: usize = item.len;

            var hash_hex_buf: [64]u8 = undefined;
            const hash_hex = std.fmt.bufPrint(&hash_hex_buf, "{}", .{std.fmt.fmtSliceHexLower(&item.hash)}) catch unreachable;

            var char_hex_buf: [8]u8 = undefined;
            const char_hex = std.fmt.bufPrint(&char_hex_buf, "{}", .{std.fmt.fmtSliceHexLower(item.bytes[0..char_len])}) catch unreachable;

            try writer.print("{d}\t{d}\t{d:.6}\t{s}\t{s}\n", .{
                item.pos,
                item.timestamp_ms,
                item.surprise_score,
                hash_hex,
                char_hex,
            });
        }

        try bw.flush();
    }

    fn computeSurprise(prev: ?[]const u8, current: []const u8) f32 {
        const previous = prev orelse return 1.0;
        const a = previous[0];
        const b = current[0];
        const delta: u8 = if (a > b) a - b else b - a;
        return @as(f32, @floatFromInt(delta)) / 255.0;
    }

    pub fn forceReadAndMemorize(self: *ConversationHistory, text: []const u8) !void {
        const view = std.unicode.Utf8View.init(text) catch return error.InvalidUtf8;
        var cp_iter = view.iterator();
        var byte_pos: usize = 0;
        var prev_slice: ?[]const u8 = null;

        while (cp_iter.nextCodepointSlice()) |slice| {
            var hasher = Sha256.init(.{});
            hasher.update(&self.session_id);
            hasher.update(slice);
            var hash: [32]u8 = undefined;
            hasher.final(&hash);

            var hash_hex_buf: [64]u8 = undefined;
            const hash_hex_view = std.fmt.bufPrint(&hash_hex_buf, "{}", .{std.fmt.fmtSliceHexLower(&hash)}) catch unreachable;

            if (self.seen.contains(hash_hex_view)) {
                byte_pos += slice.len;
                prev_slice = slice;
                continue;
            }

            const hash_hex = try self.allocator.dupe(u8, hash_hex_view);
            errdefer self.allocator.free(hash_hex);

            var bytes: [4]u8 = [_]u8{0} ** 4;
            @memcpy(bytes[0..slice.len], slice);

            try self.chars.append(self.allocator, .{
                .bytes = bytes,
                .len = @intCast(slice.len),
                .pos = byte_pos,
                .timestamp_ms = std.time.milliTimestamp(),
                .hash = hash,
                .surprise_score = computeSurprise(prev_slice, slice),
            });
            try self.seen.put(hash_hex, {});
            byte_pos += slice.len;
            prev_slice = slice;
        }
    }

    pub fn dumpText(self: *ConversationHistory, allocator: Allocator) ![]u8 {
        var out: ArrayListUnmanaged(u8) = .empty;
        errdefer out.deinit(allocator);

        for (self.chars.items) |item| {
            const char_len: usize = item.len;
            try out.appendSlice(allocator, item.bytes[0..char_len]);
        }

        return out.toOwnedSlice(allocator);
    }
};

fn writeJsonString(writer: anytype, value: []const u8) !void {
    try writer.writeByte('"');
    for (value) |c| {
        switch (c) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            else => {
                if (c < 0x20) {
                    try writer.print("\\u{X:0>4}", .{@as(u16, c)});
                } else {
                    try writer.writeByte(c);
                }
            },
        }
    }
    try writer.writeByte('"');
}

fn buildRequestBody(allocator: Allocator, model: []const u8, messages: []const Message) ![]u8 {
    var out = std.ArrayList(u8).init(allocator);
    errdefer out.deinit();

    const writer = out.writer();
    try writer.writeAll("{\"model\":");
    try writeJsonString(writer, model);
    try writer.writeAll(",\"messages\":[");
    for (messages, 0..) |msg, i| {
        if (i != 0) try writer.writeByte(',');
        try writer.writeAll("{\"role\":");
        try writeJsonString(writer, msg.role);
        try writer.writeAll(",\"content\":");
        try writeJsonString(writer, msg.content);
        try writer.writeByte('}');
    }
    try writer.writeAll("]}");

    return out.toOwnedSlice();
}

pub fn main() !void {
    var gpa: std.heap.GeneralPurposeAllocator(.{}) = .init;
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var history = try ConversationHistory.init(allocator, "conversation.zigdb");
    defer history.deinit();

    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    const user_input = if (args.len >= 2) args[1] else "What is AI?";
    try history.forceReadAndMemorize(user_input);

    const history_text = try history.dumpText(allocator);
    defer allocator.free(history_text);

    const system_prompt = "You are a helpful assistant.";
    const model_name = "xiaomi/mimo-v2.5-pro";

    const messages = [_]Message{
        .{ .role = "system", .content = system_prompt },
        .{ .role = "system", .content = history_text },
        .{ .role = "user", .content = user_input },
    };

    const body = try buildRequestBody(allocator, model_name, messages[0..]);
    defer allocator.free(body);

    const api_key = std.process.getEnvVarOwned(allocator, "HPC_AI_API_KEY") catch |err| switch (err) {
        error.EnvironmentVariableNotFound => return error.MissingApiKey,
        else => return err,
    };
    defer allocator.free(api_key);

    const authorization_header = try std.fmt.allocPrint(allocator, "Bearer {s}", .{api_key});
    defer allocator.free(authorization_header);

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    var response_body = std.ArrayList(u8).init(allocator);
    defer response_body.deinit();

    const fetch_result = try client.fetch(.{
        .location = .{ .uri = uri },
        .method = .POST,
        .payload = body,
        .extra_headers = &.{
            .{ .name = "Authorization", .value = authorization_header },
            .{ .name = "Content-Type", .value = "application/json" },
            .{ .name = "User-Agent", .value = "zig-conversation-client/1.0" },
        },
        .response_storage = .{ .dynamic = &response_body },
    });

    const status_code = @intFromEnum(fetch_result.status);
    if (status_code < 200 or status_code >= 300) return error.HttpRequestFailed;

    const resp_body = response_body.items;

    const parsed = try std.json.parseFromSlice(ChatResponse, allocator, resp_body, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();

    if (parsed.value.choices.len == 0) return error.InvalidApiResponse;
    const content = parsed.value.choices[0].message.content orelse "";
    try history.forceReadAndMemorize(content);
    std.debug.print("{s}\n", .{content});
}
